options(stringsAsFactors=FALSE)
suppressPackageStartupMessages(library(data.table))
root<-"D:/PDAC_P1";raw<-file.path(root,"data/03_functional/DepMap24Q4/raw");prism<-file.path(root,"data/03_functional/PRISM20Q2/raw");out<-file.path(root,"analysis/11_methodology_review/DepMap_PRISM_pharmacology")
models<-fread(file.path(raw,"Model.csv"))[OncotreeLineage=="Pancreas",.(ModelID,CellLineName,CCLEName)]
cf<-file.path(raw,"CRISPRGeneEffect.csv");h<-names(fread(cf,nrows=0,check.names=FALSE));genes<-c("EPAS1","MARCKS","HERPUD1","TACC1");cols<-c(h[1],unlist(lapply(genes,function(g)h[startsWith(h,paste0(g," ("))][1])));cr<-fread(cf,select=cols,check.names=FALSE);setnames(cr,1,"ModelID");setnames(cr,names(cr),sub(" \\([0-9]+\\)$","",names(cr)))
lf<-file.path(prism,"prism-repurposing-20q2-primary-screen-replicate-collapsed-logfold-change.csv");ph<-names(fread(lf,nrows=0,check.names=FALSE));dc<-c("BRD-K81916719-001-13-9::2.5::HTS","BRD-K56751279-300-01-4::2.5::HTS");p<-fread(lf,select=c(ph[1],dc),check.names=FALSE);setnames(p,1,"ModelID");setnames(p,dc,c("triclabendazole_logFC","Y39983_logFC"))
d<-Reduce(function(x,y)merge(x,y,by="ModelID"),list(models,cr,p));ans<-rbindlist(lapply(c("triclabendazole_logFC","Y39983_logFC"),function(dr)rbindlist(lapply(genes,function(g){q<-d[is.finite(get(g))&is.finite(get(dr))];ct<-cor.test(q[[g]],q[[dr]],method="spearman",exact=FALSE);data.table(drug=dr,gene=g,n=nrow(q),spearman_rho=unname(ct$estimate),P=ct$p.value)}))));ans[,FDR:=p.adjust(P,"BH")]
fwrite(d,file.path(out,"DepMap_CRISPR_PRISM_matched_PDAC.tsv"),sep="\t");fwrite(ans,file.path(out,"DepMap_CRISPR_PRISM_association_results.tsv"),sep="\t");writeLines(c("# DepMap CRISPR–PRISM PDAC association","",paste0("- Matched PDAC models: ",nrow(d),"."),"- Correlates CRISPR gene-effect (more negative = stronger in-vitro dependency) with PRISM viability logFC (more negative = greater viability loss).","- This tests association between tumor-cell intrinsic dependency and compound sensitivity; it does not test endothelial-specific EPAS1 mechanism or direct drug binding."),file.path(out,"DepMap_CRISPR_PRISM_report.md"))
